package world

import (
	"fmt"
	"math"
)

// NameMapping 描述旧规则中一个名称到新规则名称的显式转换关系。
//
// From 必须是来源记录旧规则中存在的地点或物品种类，To 必须是目标规则中
// 存在的对应名称；空名称、来源不存在于旧规则或目标不存在于新规则都在
// 预览时返回规则错误。
type NameMapping struct {
	// From 是旧规则中的地点或物品种类名称。
	From string
	// To 是新规则中的对应名称。
	To string
}

// MigrationPreview 是把槽当前最新记录按对应关系显式迁移到目标规则的
// 预览结果。
//
// 预览只读：返回所依据的来源记录标识、旧新版本、按对应关系转换后的完整
// 世界状态（深拷贝）以及是否可提交。它不改变槽指向、历史或任何记录文件；
// 修改返回的状态也不影响存档。
type MigrationPreview struct {
	// RecordID 是所依据的来源记录标识（槽当前最新记录）。
	RecordID RecordID
	// OldVersion 是来源记录的规则版本。
	OldVersion string
	// TargetVersion 是目标规则版本。
	TargetVersion string
	// State 是转换后的完整世界状态（深拷贝），规则已替换为目标规则。
	// 正式迁移以排他锁下重新读取和计算的结果为准，不使用调用方可能改过
	// 的本状态。
	State State
	// Committable 表示转换后的状态能否在目标规则下提交（无阻碍）。
	Committable bool
	// Blockers 是全部阻碍，排序与升级检查一致；重复预览输出顺序一致。
	Blockers []Blocker
}

// MigrationResult 是正式迁移的返回结果。
type MigrationResult struct {
	// Preview 是对来源记录与目标规则的预览结果（排他锁下重新读取并计算）。
	Preview MigrationPreview
	// Record 是成功时新记录的元信息；被阻碍时为零值。
	Record RecordInfo
}

// validateMappings 校验转换对应关系：来源必须存在于旧规则，目标必须存在
// 于新规则，名称非空，同一来源不重复指定。即使没有角色使用这些名称也要
// 检查。
func validateMappings(old, target Rules, locations, items []NameMapping) error {
	oldLocs := make(map[string]struct{}, len(old.Locations))
	for _, l := range old.Locations {
		oldLocs[l] = struct{}{}
	}
	newLocs := make(map[string]struct{}, len(target.Locations))
	for _, l := range target.Locations {
		newLocs[l] = struct{}{}
	}
	if err := validateMappingSet("地点", locations, oldLocs, newLocs); err != nil {
		return err
	}

	oldKinds := make(map[string]struct{}, len(old.ItemKinds))
	for _, k := range old.ItemKinds {
		oldKinds[k] = struct{}{}
	}
	newKinds := make(map[string]struct{}, len(target.ItemKinds))
	for _, k := range target.ItemKinds {
		newKinds[k] = struct{}{}
	}
	return validateMappingSet("物品种类", items, oldKinds, newKinds)
}

func validateMappingSet(kind string, mappings []NameMapping, oldNames, newNames map[string]struct{}) error {
	seen := make(map[string]struct{}, len(mappings))
	for i, m := range mappings {
		if m.From == "" {
			return ruleErrorf("%s转换关系 %d 的来源名称为空", kind, i)
		}
		if m.To == "" {
			return ruleErrorf("%s转换关系 %d 的目标名称为空", kind, i)
		}
		if _, ok := oldNames[m.From]; !ok {
			return ruleErrorf("%s转换关系的来源 %q 不存在于旧规则", kind, m.From)
		}
		if _, ok := newNames[m.To]; !ok {
			return ruleErrorf("%s转换关系的目标 %q 不存在于新规则", kind, m.To)
		}
		if _, dup := seen[m.From]; dup {
			return ruleErrorf("%s转换关系的来源 %q 重复指定", kind, m.From)
		}
		seen[m.From] = struct{}{}
	}
	return nil
}

// applyMigration 按对应关系转换状态：角色按对应关系改变所在地点（无需
// 符合旧道路），物品改变种类但不增减数量；多个条目转换成同一种物品时
// 合并数量，按原列表中首次出现的位置保留一个条目。转换只作用于原始名称
// 一次，不沿对应关系连续替换，因此互换名称也有确定结果。未指定的名称
// 保持原样。种子、时间片、角色标识及角色排列保持不变。
//
// 合并数量或携带总量超出 int 范围时返回规则错误，不回绕也不丢弃物品。
func applyMigration(st State, locations, items []NameMapping) (State, error) {
	locLookup := make(map[string]string, len(locations))
	for _, m := range locations {
		locLookup[m.From] = m.To
	}
	itemLookup := make(map[string]string, len(items))
	for _, m := range items {
		itemLookup[m.From] = m.To
	}

	out := cloneState(st)

	for i := range out.Characters {
		if to, ok := locLookup[out.Characters[i].Location]; ok {
			out.Characters[i].Location = to
		}
	}

	for i := range out.Characters {
		ch := &out.Characters[i]
		merged := make([]CharacterItem, 0, len(ch.Items))
		indexByName := make(map[string]int, len(ch.Items))
		for _, it := range ch.Items {
			name := it.Item
			if to, ok := itemLookup[name]; ok {
				name = to
			}
			if idx, ok := indexByName[name]; ok {
				sum, ok := addInt(merged[idx].Count, it.Count)
				if !ok {
					return State{}, ruleErrorf("角色 %q 的物品 %q 合并数量超出整数范围", ch.ID, name)
				}
				merged[idx].Count = sum
			} else {
				indexByName[name] = len(merged)
				merged = append(merged, CharacterItem{Item: name, Count: it.Count})
			}
		}
		ch.Items = merged

		// 携带总量溢出检查：各物品数量都合法，但不同物品相加可能超出
		// int 范围，同样不能回绕或丢弃。
		total := 0
		for _, it := range ch.Items {
			sum, ok := addInt(total, it.Count)
			if !ok {
				return State{}, ruleErrorf("角色 %q 携带总量超出整数范围", ch.ID)
			}
			total = sum
		}
	}
	return out, nil
}

// addInt 做一次带溢出检查的 int 加法，返回结果与是否溢出。
func addInt(a, b int) (int, bool) {
	if b > 0 && a > math.MaxInt-b {
		return 0, false
	}
	if b < 0 && a < math.MinInt-b {
		return 0, false
	}
	return a + b, true
}

// migrationComputeLocked 在调用方已持锁（共享或排他均可）的前提下读取并
// 校验槽当前最新记录，校验转换对应关系，计算转换后的状态与阻碍。不写入。
func (a *Archive) migrationComputeLocked(slot string, acceptedVersions []string, target Rules, locations, items []NameMapping) (MigrationPreview, *envelope, error) {
	latest, err := a.readLatestLocked(slot)
	if err != nil {
		return MigrationPreview{}, nil, err
	}
	env, err := a.loadAndVerifyLocked(latest)
	if err != nil {
		if ce, ok := err.(*CorruptError); ok {
			ce.Slot = slot
		}
		return MigrationPreview{}, nil, err
	}
	if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
		return MigrationPreview{}, nil, &VersionRejectedError{
			Slot:     slot,
			Record:   latest,
			Version:  env.State.Rules.Version,
			Accepted: append([]string(nil), acceptedVersions...),
		}
	}
	if target.Version == env.State.Rules.Version {
		return MigrationPreview{}, nil, &RuleError{Reason: "目标规则版本必须与来源记录版本不同"}
	}
	if err := validateMappings(env.State.Rules, target, locations, items); err != nil {
		return MigrationPreview{}, nil, err
	}
	transformed, err := applyMigration(env.State, locations, items)
	if err != nil {
		return MigrationPreview{}, nil, err
	}
	// 转换后的状态保存目标规则。
	transformed.Rules = cloneRules(target)
	blockers := checkCompatibility(transformed, target)
	preview := MigrationPreview{
		RecordID:      latest,
		OldVersion:    env.State.Rules.Version,
		TargetVersion: target.Version,
		State:         transformed,
		Committable:   len(blockers) == 0,
		Blockers:      blockers,
	}
	return preview, env, nil
}

// PreviewMigration 预览把槽当前最新记录按对应关系显式迁移到目标规则。
//
// 传入槽名、可接受的旧版本集合、目标规则，以及旧地点到新地点、旧物品到
// 新物品的对应关系，返回所依据的来源记录标识、旧新版本、转换后的完整
// 世界状态（深拷贝）及是否可提交。转换只作用于原始名称一次，不沿对应
// 关系连续替换；未指定的名称保持原样。转换后仍有缺失地点、不被允许的
// 物品或超过目标携带上限时，一次列出全部阻碍，重复预览输出顺序一致。
//
// 预览只读：不改变世界、历史或槽当前记录，修改返回的状态也不影响存档。
// 目标规则须满足规则自身的合法性要求且版本与来源不同；对应关系的来源
// 必须存在于旧规则、目标必须存在于新规则（即使没有角色使用也要检查），
// 空目标或未知名称返回规则错误；合并数量或携带总量超出 int 范围返回规则
// 错误。来源缺失、损坏或版本不被接受时沿用已有对应错误，不自动挑选历史
// 记录。
func (a *Archive) PreviewMigration(slot string, acceptedVersions []string, target Rules, locations, items []NameMapping) (MigrationPreview, error) {
	if !validSlotName(slot) {
		return MigrationPreview{}, &NotFoundError{Slot: slot}
	}
	if err := validateRules(target); err != nil {
		return MigrationPreview{}, err
	}
	lock, err := acquireSharedLock(a.dir)
	if err != nil {
		return MigrationPreview{}, err
	}
	defer lock.release()
	preview, _, err := a.migrationComputeLocked(slot, acceptedVersions, target, locations, items)
	if err != nil {
		return MigrationPreview{}, err
	}
	return preview, nil
}

// Migrate 在预览后正式迁移：用目标规则与转换后的状态生成一条以来源为父
// 的新记录并加入本槽保存次序。
//
// 传入与预览相同的条件，并带预览返回的来源记录标识 source。提交时在
// 排他锁下重新读取并完整校验来源，重新校验目标规则与对应关系、重新计算
// 转换后的状态与阻碍，绝不使用调用方可能改过的预览状态：
//
//   - source 为空，或槽已不再指向该来源（被并发覆盖、升级、确认恢复或
//     另一次迁移抢先提交），返回 *ConflictError。
//   - 来源缺失、损坏或版本不被接受分别返回已有的不存在、损坏或版本拒绝
//     错误，不改选其他记录。
//   - 仍有阻碍时返回阻碍信息并拒绝保存，不改变当前记录或历史。
//
// 成功后产生一条以来源为父的新记录，保存目标规则与转换后的状态，加入
// 本槽保存次序；种子、时间片、角色标识及角色排列保持原样。与覆盖、升级、
// 确认恢复或另一次迁移竞争时，同一来源最多一个成功。任何拒绝都不改变
// 当前记录或历史；中断后重开只能看到迁移前或迁移后的完整记录与历史。
// 旧记录及已有分支保留原状态，恢复读取仍能找到旧版本；迁移后的记录可
// 继续按新规则移动、改变物品并保存，普通读取不自动转换。
func (a *Archive) Migrate(slot string, acceptedVersions []string, target Rules, locations, items []NameMapping, source RecordID) (MigrationResult, error) {
	if !validSlotName(slot) {
		return MigrationResult{}, &NotFoundError{Slot: slot}
	}
	if source == "" {
		return MigrationResult{}, &ConflictError{Slot: slot, Reason: "迁移必须提供所依据的来源记录标识"}
	}
	if err := validateRules(target); err != nil {
		return MigrationResult{}, err
	}
	lock, err := acquireLock(a.dir)
	if err != nil {
		return MigrationResult{}, err
	}
	defer lock.release()

	oldPointer, err := a.readSlotPointerLocked(slot)
	if err != nil {
		return MigrationResult{}, err
	}
	// 乐观并发控制：槽必须仍指向预览时的来源记录。
	if oldPointer.Latest != source {
		return MigrationResult{}, &ConflictError{
			Slot:   slot,
			Reason: "所依据的来源记录已不是该槽最新记录",
		}
	}

	// 排他锁下重新读取、校验并计算，不采信调用方带回的任何状态。
	preview, _, err := a.migrationComputeLocked(slot, acceptedVersions, target, locations, items)
	if err != nil {
		return MigrationResult{}, err
	}
	if !preview.Committable {
		return MigrationResult{Preview: preview}, &RuleError{
			Reason: fmt.Sprintf("迁移被阻碍: 转换后的状态无法在目标规则下提交（%d 处阻碍）", len(preview.Blockers)),
		}
	}

	// 保存目标规则与排他锁下重新计算出的转换结果；以来源为父，沿用
	// 共同的新记录组装、落盘与槽指针提交路径。记录完整落盘后才原子
	// 更新指针：新记录前置进保存次序，旧历史原样保留。崩溃在这一步
	// 之前时槽保持迁移前的指向与历史，新记录因不在历史索引中而不会
	// 进入恢复候选。
	info, err := a.appendSlotRecordLocked(slotSave{
		slot:          slot,
		oldPointer:    oldPointer,
		parent:        source,
		historyAnchor: source,
		state:         preview.State,
	})
	if err != nil {
		return MigrationResult{}, err
	}
	return MigrationResult{Preview: preview, Record: info}, nil
}

package world

import (
	"fmt"
	"math/big"
	"sort"
)

// BlockerKind 表示升级阻碍的类型。
type BlockerKind string

const (
	// BlockerLocation 表示角色所在地点在目标规则中已不存在。
	BlockerLocation BlockerKind = "location"
	// BlockerItem 表示角色携带的某种物品在目标规则中已不被允许。
	BlockerItem BlockerKind = "item"
	// BlockerLimit 表示角色携带总量超过目标规则给出的上限。
	BlockerLimit BlockerKind = "limit"
)

// Blocker 描述一条“目标规则无法原样承接当前角色状态”的具体阻碍。
type Blocker struct {
	// Character 是受阻碍的角色标识。
	Character string
	// Kind 是阻碍类型。
	Kind BlockerKind
	// Location 是缺失的地点（Kind 为 BlockerLocation 时有值）。
	Location string
	// Item 是被移除的物品种类（Kind 为 BlockerItem 时有值）。
	Item string
	// Total 是角色当前携带总量（Kind 为 BlockerLimit 且 TotalOverflow
	// 为 false 时有值，此时它就是真实总量）。
	Total int
	// TotalOverflow 表示真实携带总量超出 int 能表示的范围（来源规则未设
	// 上限时可能出现）：此时 Total 不代表实际总量，调用方应改用
	// TotalText 给出的完整十进制真实总量。
	TotalOverflow bool
	// TotalText 是真实携带总量的完整十进制表示（仅 TotalOverflow 为
	// true 时有值）。
	TotalText string
	// Limit 是目标规则给出的新上限（Kind 为 BlockerLimit 时有值）。
	Limit int
}

// UpgradeCheck 描述对槽当前最新记录与目标规则的兼容性检查结果。
type UpgradeCheck struct {
	// RecordID 是所检查的来源记录标识（槽当前最新记录）。
	RecordID RecordID
	// OldVersion 是来源记录的规则版本。
	OldVersion string
	// TargetVersion 是目标规则版本。
	TargetVersion string
	// Compatible 表示目标规则能否原样承接当前角色状态。
	Compatible bool
	// Blockers 是全部阻碍，按角色标识、物品标识排序；重复检查输出顺序一致。
	Blockers []Blocker
}

// UpgradeResult 是升级的返回结果。
type UpgradeResult struct {
	// Check 是对当前来源记录与目标规则的兼容性检查结果。
	Check UpgradeCheck
	// Record 是成功时新记录的元信息；被阻碍时为零值。
	Record RecordInfo
}

// checkCompatibility 计算用 target 规则原样承接 st 中全部角色状态的阻碍。
//
// 兼容只判断能否原样承接当前角色状态：每个角色所在地点仍存在，已列出的
// 物品种类仍被允许（数量为零也算），各角色携带总量不超过目标上限（按真实
// 总量精确求和，不因回绕放过超限；真实总量超出 int 范围时阻碍置
// TotalOverflow 并以 TotalText 给出完整十进制总量）；目标中没有该角色上限
// 时表示不设上限。允许删去无人所在的地点、不再出现的物品种类或旧连通关系，
// 也允许增加内容。升级后移动和物品变化按目标规则处理。
func checkCompatibility(st State, target Rules) []Blocker {
	locSet := make(map[string]struct{}, len(target.Locations))
	for _, l := range target.Locations {
		locSet[l] = struct{}{}
	}
	kindSet := make(map[string]struct{}, len(target.ItemKinds))
	for _, k := range target.ItemKinds {
		kindSet[k] = struct{}{}
	}
	var blockers []Blocker
	for _, ch := range st.Characters {
		if _, ok := locSet[ch.Location]; !ok {
			blockers = append(blockers, Blocker{
				Character: ch.ID,
				Kind:      BlockerLocation,
				Location:  ch.Location,
			})
		}
		for _, it := range ch.Items {
			if _, ok := kindSet[it.Item]; !ok {
				blockers = append(blockers, Blocker{
					Character: ch.ID,
					Kind:      BlockerItem,
					Item:      it.Item,
				})
			}
		}
		// 携带上限按真实总量判断：精确求和，不因加法回绕而放过超限。
		// 真实总量能用 int 表示时沿用 Total 字段；超出 int 范围时置
		// TotalOverflow 并给出完整十进制 TotalText。
		if limit, ok := target.CarryLimits[ch.ID]; ok {
			if total := carryTotal(ch.Items); total.Cmp(bigInt(limit)) > 0 {
				b := Blocker{
					Character: ch.ID,
					Kind:      BlockerLimit,
					Limit:     limit,
				}
				if total.Cmp(maxIntBig) <= 0 {
					b.Total = int(total.Int64())
				} else {
					b.TotalOverflow = true
					b.TotalText = total.String()
				}
				blockers = append(blockers, b)
			}
		}
	}
	// 同类问题按角色标识、物品标识排序；location/limit 阻碍没有物品标识，
	// 以空物品标识参与排序，保证重复检查输出顺序一致。跨类别按
	// location、item、limit 的自然顺序分组，便于阅读。
	kindRank := func(k BlockerKind) int {
		switch k {
		case BlockerLocation:
			return 0
		case BlockerItem:
			return 1
		case BlockerLimit:
			return 2
		}
		return 3
	}
	sort.SliceStable(blockers, func(i, j int) bool {
		if blockers[i].Character != blockers[j].Character {
			return blockers[i].Character < blockers[j].Character
		}
		if blockers[i].Kind != blockers[j].Kind {
			return kindRank(blockers[i].Kind) < kindRank(blockers[j].Kind)
		}
		return blockers[i].Item < blockers[j].Item
	})
	return blockers
}

// checkUpgradeLocked 在调用方已持锁（共享或排他均可）的前提下读取并校验
// 槽当前最新记录，计算目标规则的兼容性。返回检查结果与来源记录信封。
func (a *Archive) checkUpgradeLocked(slot string, acceptedVersions []string, target Rules) (UpgradeCheck, *envelope, error) {
	latest, err := a.readLatestLocked(slot)
	if err != nil {
		return UpgradeCheck{}, nil, err
	}
	env, err := a.loadAndVerifyLocked(latest)
	if err != nil {
		if ce, ok := err.(*CorruptError); ok {
			ce.Slot = slot
		}
		return UpgradeCheck{}, nil, err
	}
	if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
		return UpgradeCheck{}, nil, &VersionRejectedError{
			Slot:     slot,
			Record:   latest,
			Version:  env.State.Rules.Version,
			Accepted: append([]string(nil), acceptedVersions...),
		}
	}
	if target.Version == env.State.Rules.Version {
		return UpgradeCheck{}, nil, &RuleError{Reason: "目标规则版本必须与来源记录版本不同"}
	}
	check := UpgradeCheck{
		RecordID:      latest,
		OldVersion:    env.State.Rules.Version,
		TargetVersion: target.Version,
	}
	blockers := checkCompatibility(env.State, target)
	check.Compatible = len(blockers) == 0
	check.Blockers = blockers
	return check, env, nil
}

// CheckUpgrade 检查槽当前最新记录能否在目标规则下继续使用。
//
// 检查只读取来源记录并计算兼容性，不改变世界、历史或槽当前记录，也不会
// 替换记录中的规则。target 必须先满足规则自身的合法性要求，且版本与来源
// 记录不同（版本只按相等判断，不按数字大小限制升级）。
//
// 目标规则非法返回 *RuleError；版本相同返回 *RuleError；来源损坏返回
// *CorruptError；来源版本不在 acceptedVersions 内返回 *VersionRejectedError；
// 槽不存在沿用现有不存在错误。
func (a *Archive) CheckUpgrade(slot string, acceptedVersions []string, target Rules) (UpgradeCheck, error) {
	if !validSlotName(slot) {
		return UpgradeCheck{}, &NotFoundError{Slot: slot}
	}
	if err := validateRules(target); err != nil {
		return UpgradeCheck{}, err
	}
	lock, err := acquireSharedLock(a.dir)
	if err != nil {
		return UpgradeCheck{}, err
	}
	defer lock.release()
	check, _, err := a.checkUpgradeLocked(slot, acceptedVersions, target)
	if err != nil {
		return UpgradeCheck{}, err
	}
	return check, nil
}

// Upgrade 在检查通过后用目标规则生成一条新记录。
//
// 传入与 CheckUpgrade 相同的条件，并带调用方预期的最新记录标识 expected。
// 提交时在排他锁下重新判断当前来源：仍有阻碍则返回相同的阻碍信息并拒绝
// 写入；expected 为空或已不是该槽最新记录时返回现有冲突错误。
//
// 被拒绝的升级不增加历史记录，也不改变槽当前记录。成功后槽增加一条完整
// 的新记录，以被升级记录为父，保存目标规则；种子、时间片、角色位置及
// 物品数量和排列保持原样。并发升级或升级与普通覆盖竞争时，只有 expected
// 与最新记录一致的一个成功，其余收到冲突。
func (a *Archive) Upgrade(slot string, acceptedVersions []string, target Rules, expected RecordID) (UpgradeResult, error) {
	if !validSlotName(slot) {
		return UpgradeResult{}, &NotFoundError{Slot: slot}
	}
	if err := validateRules(target); err != nil {
		return UpgradeResult{}, err
	}
	if expected == "" {
		return UpgradeResult{}, &ConflictError{Slot: slot, Reason: "升级必须提供所依据的记录标识"}
	}
	lock, err := acquireLock(a.dir)
	if err != nil {
		return UpgradeResult{}, err
	}
	defer lock.release()

	oldPointer, err := a.readSlotPointerLocked(slot)
	if err != nil {
		return UpgradeResult{}, err
	}
	latest := oldPointer.Latest
	if latest != expected {
		return UpgradeResult{}, &ConflictError{
			Slot:   slot,
			Reason: "所依据的记录已不是该槽最新记录",
		}
	}

	check, env, err := a.checkUpgradeLocked(slot, acceptedVersions, target)
	if err != nil {
		return UpgradeResult{}, err
	}
	if !check.Compatible {
		return UpgradeResult{Check: check}, &RuleError{
			Reason: fmt.Sprintf("升级被阻碍: 目标规则无法承接当前角色状态（%d 处阻碍）", len(check.Blockers)),
		}
	}

	// 升级保存目标规则，种子、时间片、角色位置及物品数量和排列原样保留；
	// 以被升级记录为父，沿用共同的新记录组装、落盘与槽指针提交路径。
	newState := State{
		Seed:       env.State.Seed,
		Rules:      cloneRules(target),
		Time:       env.State.Time,
		Characters: cloneCharacters(env.State.Characters),
	}
	info, err := a.appendSlotRecordLocked(slotSave{
		slot:          slot,
		oldPointer:    oldPointer,
		parent:        expected,
		historyAnchor: latest,
		state:         newState,
	})
	if err != nil {
		return UpgradeResult{}, err
	}
	return UpgradeResult{Check: check, Record: info}, nil
}

