+// carryTotal 精确求和同一角色全部物品数量的真实总量：使用不回绕的
+// 精确整数运算，不截断数量、不丢弃条目、不改变排列。不同角色的总量
+// 分别计算，互不合并。
+func carryTotal(items []CharacterItem) *big.Int {
+	total := new(big.Int)
+	for _, it := range items {
+		total.Add(total, bigInt(it.Count))
+	}
+	return total
+}
